/** Small pages may share a bounded cache without relaxing its total tuple storage or snapshot ownership limits. */
@Timeout(60)
class LmdbPersistentAdjacencyAdaptivePointCacheTest {

	private static final long TUPLE_PAYLOAD_BUDGET = 512L * 1024;
	private static final int READY_ENTRY_LIMIT = 128;
	private static final long BYTES_PER_TUPLE = 3L * Long.BYTES;

	@TempDir
	Path directory;

	@ParameterizedTest
	@EnumSource(Route.class)
	void collidingAdmissionFingerprintsNeverShareMembershipAnswers(Route route) throws Exception {
		Quad firstA = new Quad(1_000, 32, 2_000, 0);
		Quad presentA = new Quad(1_001, 32, 2_001, 0);
		Quad firstB = new Quad(1_000, 257, 2_000, 0);
		Quad presentB = new Quad(1_001, 257, 3_001, 0);
		Quad absentA = new Quad(1_001, 32, 3_001, 0);
		Quad absentB = new Quad(1_001, 257, 2_001, 0);
		byte[] fenceA = pointFence(firstA);
		byte[] fenceB = pointFence(firstB);
		assertThat(fenceA).isNotEqualTo(fenceB);
		// Changing adjacent predicate bytes by +1 and -31 cancels in Arrays.hashCode's base-31 recurrence.
		assertThat(Arrays.hashCode(fenceA)).isEqualTo(Arrays.hashCode(fenceB));
		for (boolean firstTouchA : new boolean[] { true, false }) {
			Path storeDirectory = Files.createDirectory(directory.resolve(firstTouchA ? "a-first" : "b-first"));
			try (Fixture fixture = new Fixture(storeDirectory, 0, 0, false)) {
				fixture.store.startTransaction();
				fixture.add(firstA);
				fixture.add(presentA);
				fixture.add(firstB);
				fixture.add(presentB);
				fixture.commit(true);
				try (Txn reader = fixture.snapshot()) {
					// Exact native gets prove these really are separate physical fences. Raw decode leaves shared
					// point admission cold, and the positive row counts prevent SCAN's row-absence shortcut.
					assertCollisionPage(fixture, reader, fenceA, presentA);
					assertCollisionPage(fixture, reader, fenceB, presentB);
					try (CodecWork work = new CodecWork()) {
						Quad firstPresent = firstTouchA ? presentA : presentB;
						Quad otherAbsent = firstTouchA ? absentB : absentA;
						Quad otherPresent = firstTouchA ? presentB : presentA;
						assertThat(fixture.point(route, reader, firstPresent)).isTrue();
						assertThat(work.walks).as("the first page touch validates before publishing a hint")
								.isEqualTo(1);
						long beforeCollision = work.walks;
						assertThat(fixture.point(route, reader, otherAbsent)).isFalse();
						assertThat(work.walks - beforeCollision)
								.as("a colliding hint must fully validate the other page before answering")
								.isEqualTo(1);
						assertThat(fixture.point(route, reader, otherPresent)).isTrue();
						for (int repeat = 0; repeat < 3; repeat++) {
							assertThat(fixture.point(route, reader, presentA)).isTrue();
							assertThat(fixture.point(route, reader, presentB)).isTrue();
						}
						for (int repeat = 0; repeat < 4; repeat++) {
							assertThat(fixture.point(route, reader, absentB)).isFalse();
							assertThat(fixture.point(route, reader, presentB)).isTrue();
							assertThat(fixture.point(route, reader, absentA)).isFalse();
							assertThat(fixture.point(route, reader, presentA)).isTrue();
						}
					}
					fixture.assertModel(reader, fixture.model);
				}
			}
		}
	}

	@ParameterizedTest
	@EnumSource(Route.class)
	void sixtyFourSmallPagesReuseValidationAcrossPooledReaders(Route route) throws Exception {
		int predicates = 64;
		int degree = 64;
		try (Fixture fixture = new Fixture(directory, predicates, degree, false); Txn first = fixture.snapshot()) {
			assertThat(predicates * degree * BYTES_PER_TUPLE).isLessThan(TUPLE_PAYLOAD_BUDGET);
			assertPageSizes(fixture, first, predicates, degree);
			long repeatedWalks;
			try (CodecWork work = new CodecWork()) {
				for (int predicate = 0; predicate < predicates; predicate++) {
					// Adjacent touches make admission independent of collisions between separate hint slots.
					Quad target = quad(predicate, 8);
					assertThat(fixture.point(route, first, target)).isTrue();
					assertThat(fixture.point(route, first, target)).isTrue();
				}
				long primingWalks = work.walks;
				assertThat(primingWalks).as("each cold page is fully validated before any shared answer")
						.isBetween((long) predicates, 2L * predicates);
				for (int repeat = 0; repeat < 3; repeat++) {
					try (Txn pooled = fixture.snapshot()) {
						assertThat(pooled.nativeTransactionId()).isEqualTo(first.nativeTransactionId());
						for (int predicate = 0; predicate < predicates; predicate++) {
							Quad target = quad(predicate, (13 * predicate + repeat) % degree);
							assertThat(fixture.point(route, pooled, target)).isTrue();
							assertThat(fixture.point(route, pooled, gap(target))).isFalse();
						}
					}
				}
				repeatedWalks = work.walks - primingWalks;
			}
			fixture.assertModel(first, fixture.model);
			// The initial 16-entry implementation fails only this work assertion after all semantic controls above.
			assertThat(repeatedWalks).as("64 small ready pages fit the shared byte and entry budgets").isZero();
		}
	}

	@Test
	void fullPagesAcrossSnapshotsCannotExceedTheTuplePayloadBudget() throws Exception {
		int predicates = 12;
		int degree = PersistentCsfPageCodec.MAX_PAIRS;
		try (Fixture fixture = new Fixture(directory, predicates, degree, false); Txn old = fixture.snapshot()) {
			Set<Quad> original = new HashSet<>(fixture.model);
			assertPageSizes(fixture, old, predicates, degree);
			warmPages(fixture, old, predicates, degree / 2);
			advanceSnapshot(fixture);
			try (Txn current = fixture.snapshot()) {
				assertThat(current.nativeTransactionId()).isNotEqualTo(old.nativeTransactionId());
				warmPages(fixture, current, predicates, degree / 2);
				long requiredMisses = 2L * predicates - TUPLE_PAYLOAD_BUDGET / (degree * BYTES_PER_TUPLE);
				assertThat(requiredMisses).isEqualTo(3);
				long walks;
				try (CodecWork work = new CodecWork()) {
					for (Txn snapshot : new Txn[] { old, current }) {
						for (int predicate = 0; predicate < predicates; predicate++) {
							Quad target = quad(predicate, degree / 2);
							assertThat(fixture.point(Route.HAS, snapshot, target)).isTrue();
							assertThat(fixture.point(Route.SCAN, snapshot, gap(target))).isFalse();
						}
					}
					walks = work.walks;
				}
				fixture.assertModel(old, original);
				fixture.assertModel(current, fixture.model);
				assertThat(walks).as("24 snapshot/page identities cannot retain 24 full decoded pages in 512 KiB")
						.isGreaterThanOrEqualTo(requiredMisses);
			}
		}
	}

	@Test
	void tinyPagesAcrossSnapshotsStillObeyTheReadyEntryLimit() throws Exception {
		int predicates = 65;
		try (Fixture fixture = new Fixture(directory, predicates, 1, false); Txn old = fixture.snapshot()) {
			Set<Quad> original = new HashSet<>(fixture.model);
			assertPageSizes(fixture, old, predicates, 1);
			warmPages(fixture, old, predicates, 0);
			advanceSnapshot(fixture);
			try (Txn current = fixture.snapshot()) {
				assertThat(current.nativeTransactionId()).isNotEqualTo(old.nativeTransactionId());
				warmPages(fixture, current, predicates, 0);
				assertThat(2L * predicates * BYTES_PER_TUPLE).isLessThan(TUPLE_PAYLOAD_BUDGET);
				long walks;
				try (CodecWork work = new CodecWork()) {
					for (Txn snapshot : new Txn[] { old, current }) {
						for (int predicate = 0; predicate < predicates; predicate++) {
							assertThat(fixture.point(Route.HAS, snapshot, quad(predicate, 0))).isTrue();
						}
					}
					walks = work.walks;
				}
				fixture.assertModel(old, original);
				fixture.assertModel(current, fixture.model);
				assertThat(walks).as("130 tiny snapshot/page identities cannot all fit in 128 ready entries")
						.isGreaterThanOrEqualTo(2L * predicates - READY_ENTRY_LIMIT);
			}
		}
	}

	@ParameterizedTest(name = "second-touch publication={0}")
	@ValueSource(booleans = { false, true })
	void concurrentPublicationAfterWideEvictionCannotDowngradeOrReplaceAReadyPage(boolean secondTouch)
			throws Exception {
		int predicates = READY_ENTRY_LIMIT + 12;
		try (Fixture fixture = new Fixture(directory, predicates, 4, false); Txn reader = fixture.snapshot()) {
			Quad target = quad(0, 2);
			if (secondTouch) {
				assertThat(fixture.point(Route.HAS, reader, target)).isTrue();
			}
			CountDownLatch entered = new CountDownLatch(1);
			CountDownLatch release = new CountDownLatch(1);
			ExecutorService executor = Executors.newSingleThreadExecutor();
			try {
				Future<Boolean> pending = executor.submit(() -> {
					try (Txn worker = fixture.snapshot(); CodecWork work = new CodecWork()) {
						assertThat(worker.nativeTransactionId()).isEqualTo(reader.nativeTransactionId());
						work.afterNextWalk = () -> {
							entered.countDown();
							assertThat(release.await(10, TimeUnit.SECONDS)).as("release validated publication")
									.isTrue();
						};
						return fixture.point(Route.HAS, worker, target);
					}
				});
				try {
					assertThat(entered.await(10, TimeUnit.SECONDS)).as("pause outside the shared cache monitor")
							.isTrue();
					for (int predicate = 1; predicate < predicates; predicate++) {
						Quad other = quad(predicate, 2);
						assertThat(fixture.point(Route.HAS, reader, other)).isTrue();
						assertThat(fixture.point(Route.HAS, reader, other)).isTrue();
					}
					// This must remain ready when the worker publishes its older hint or equivalent decoded page.
					assertThat(fixture.point(Route.HAS, reader, target)).isTrue();
					assertThat(fixture.point(Route.HAS, reader, target)).isTrue();
				} finally {
					release.countDown();
				}
				assertThat(pending.get(10, TimeUnit.SECONDS)).isTrue();
				long walks;
				try (CodecWork work = new CodecWork()) {
					for (int repeat = 0; repeat < 3; repeat++) {
						assertThat(fixture.point(Route.HAS, reader, target)).isTrue();
						assertThat(fixture.point(Route.SCAN, reader, gap(target))).isFalse();
					}
					walks = work.walks;
				}
				fixture.assertModel(reader, fixture.model);
				assertThat(walks).as("a late publication cannot discard an already validated exact-key entry").isZero();
			} finally {
				release.countDown();
				executor.shutdownNow();
				assertThat(executor.awaitTermination(10, TimeUnit.SECONDS)).isTrue();
			}
		}
	}

	private static void assertPageSizes(Fixture fixture, Txn txn, int predicates, int expected) throws Exception {
		for (int predicate = 0; predicate < predicates; predicate++) {
			// An independent raw page decode proves the fixture's real tuple storage without warming managed lookups.
			assertThat(PersistentCsfPageCodec.decode(ByteBuffer.wrap(fixture.pageImage(txn, predicate))).size())
					.isEqualTo(expected);
		}
	}

	private static byte[] pointFence(Quad first) {
		return ByteBuffer.allocate(33)
				.put((byte) 0)
				.putLong(first.p())
				.putLong(first.s())
				.putLong(first.o())
				.putLong(first.c())
				.array();
	}

	private static void assertCollisionPage(Fixture fixture, Txn txn, byte[] fence, Quad second) throws Exception {
		long stamp = txn.lockManager().readLock();
		try (MemoryStack stack = MemoryStack.stackPush()) {
			synchronized (txn) {
				txn.ensureSnapshotValid();
				MDBVal key = MDBVal.malloc(stack).mv_data(stack.bytes(fence));
				MDBVal value = MDBVal.malloc(stack);
				E(mdb_get(txn.get(), fixture.adjacency.pagesDbi(), key, value));
				PersistentCsfPageCodec.DecodedPage page = PersistentCsfPageCodec.decode(value.mv_data());
				assertThat(page.size()).isEqualTo(2);
				assertThat(page.rowAt(0)).isEqualTo(1_000);
				assertThat(page.neighborAt(0)).isEqualTo(2_000);
				assertThat(page.contextAt(0)).isZero();
				assertThat(page.rowAt(1)).isEqualTo(second.s());
				assertThat(page.neighborAt(1)).isEqualTo(second.o());
				assertThat(page.contextAt(1)).isZero();
				assertThat(fixture.adjacency.count(txn.get(), second.s(), second.p(), -1, -1, true)).isEqualTo(1);
			}
		} finally {
			txn.lockManager().unlockRead(stamp);
		}
	}

	private static void warmPages(Fixture fixture, Txn txn, int predicates, int ordinal) throws Exception {
		for (int predicate = 0; predicate < predicates; predicate++) {
			Quad target = quad(predicate, ordinal);
			assertThat(fixture.point(Route.HAS, txn, target)).isTrue();
			assertThat(fixture.point(Route.HAS, txn, target)).isTrue();
		}
	}

	private static void advanceSnapshot(Fixture fixture) throws Exception {
		fixture.store.startTransaction();
		fixture.add(new Quad(90_000, 90_000, 90_001, 7));
		fixture.commit(true);
	}
}
